        productIds.push(result[i].value)
      } else if (result[i].key === 'BasketId') {
        basketIds.push(result[i].value)
      } else if (result[i].key === 'quantity') {
        quantities.push(result[i].value)
      }
    }

    const user = security.authenticatedUsers.from(req)
    if (user && basketIds[0] && basketIds[0] !== 'undefined' && Number(user.bid) != Number(basketIds[0])) { // eslint-disable-line eqeqeq
      res.status(401).send('{\'error\' : \'Invalid BasketId\'}')
    } else {
      const basketItem = {
        ProductId: productIds[productIds.length - 1],
        BasketId: basketIds[basketIds.length - 1],
        quantity: quantities[quantities.length - 1]
      }
      challengeUtils.solveIf(challenges.basketManipulateChallenge, () => { return user && basketItem.BasketId && basketItem.BasketId !== 'undefined' && user.bid != basketItem.BasketId }) // eslint-disable-line eqeqeq

      const basketItemInstance = BasketItemModel.build(basketItem)
      try {
        const addedBasketItem = await basketItemInstance.save()
        res.json({ status: 'success', data: addedBasketItem })
      } catch (error) {
        next(error)
      }
    }
  }
}

analysis:
In `models/user.ts`, the `email` setter selectively skips sanitization when `challenges.persistedXssUserChallenge` is active (the default challenge environment in OWASP Juice Shop).

Lines 59-68:
```typescript
set (email: string) {
  if (utils.isChallengeEnabled(challenges.persistedXssUserChallenge)) {
    challengeUtils.solveIf(challenges.persistedXssUserChallenge, () => {
      return email?.includes('<iframe src="javascript:alert(`xss`)">') ?? false
    })
  } else {
    email = security.sanitizeSecure(email)
  }
  this.setDataValue('email', email)
}
```

Data flow:
1. Source: Untrusted user input via registration endpoint (`POST /api/Users`) or user management requests where `email` is supplied.
2. Sanitization/Validation: Under the default configuration where `persistedXssUserChallenge` is enabled, sanitization via `security.sanitizeSecure(email)` is bypassed completely because it only runs inside the `else` branch.
3. Sink: `this.setDataValue('email', email)` persists the unescaped and unsanitized HTML/JavaScript payload directly into the database. When the stored email is retrieved and rendered in the frontend UI (such as in administrative views, user profiles, or order tracking), the injected script executes in the victim's session.

Conceptual Exploit Payload:
Send the following HTTP request during user registration:
```http
POST /api/Users HTTP/1.1
Host: localhost:3000
Content-Type: application/json

{
  "email": "<iframe src=\"javascript:alert(`xss`)\">@example.com",
  "password": "Password123!"
}
```
The email containing the active XSS vector is persisted without sanitization into the database and executes stored XSS when viewed.

